def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Full-color separator rows/columns, allowing occasional noise.
    candidates = {}
    for r, row in enumerate(grid):
        c = max(set(row), key=row.count)
        if row.count(c) == w and c != 2:
            candidates.setdefault(c, [set(), set()])[0].add(r)
    for j in range(w):
        col = [grid[i][j] for i in range(h)]
        c = max(set(col), key=col.count)
        if col.count(c) == h and c != 2:
            candidates.setdefault(c, [set(), set()])[1].add(j)
    # The line color is the one that forms complete straight separators.
    color, (rows, cols) = max(candidates.items(), key=lambda kv: len(kv[1][0])+len(kv[1][1]))
    for r in rows:
        for j in range(w): out[r][j] = 2
    for j in cols:
        for r in range(h): out[r][j] = 2
    return out
